46	func newTransport(base http.RoundTripper, opts *Options) (http.RoundTripper, error) {
47		var headers = opts.Headers
48		ht := &headerTransport{
49			base:    base,
50			headers: headers,
51		}
52		var trans http.RoundTripper = ht
53		trans = addOpenTelemetryTransport(trans, opts)
54		switch {
55		case opts.DisableAuthentication:
56			// Do nothing.
57		case opts.APIKey != "":
58			qp := internal.GetQuotaProject(nil, opts.Headers.Get(quotaProjectHeaderKey))
59			if qp != "" {
60				if headers == nil {
61					headers = make(map[string][]string, 1)
62				}
63				headers.Set(quotaProjectHeaderKey, qp)
64			}
65			trans = &apiKeyTransport{
66				Transport: trans,
67				Key:       opts.APIKey,
68			}
69		default:
70			var creds *auth.Credentials
71			if opts.Credentials != nil {
72				creds = opts.Credentials
73			} else {
74				var err error
75				creds, err = credentials.DetectDefault(opts.resolveDetectOptions())
76				if err != nil {
77					return nil, err
78				}
79			}
80			qp, err := creds.QuotaProjectID(context.Background())
81			if err != nil {
82				return nil, err
83			}
84			if qp != "" {
85				if headers == nil {
86					headers = make(map[string][]string, 1)
87				}
88				// Don't overwrite user specified quota
89				if v := headers.Get(quotaProjectHeaderKey); v == "" {
90					headers.Set(quotaProjectHeaderKey, qp)
91				}
92			}
93			var skipUD bool
94			if iOpts := opts.InternalOptions; iOpts != nil {
95				skipUD = iOpts.SkipUniverseDomainValidation
96			}
97			creds.TokenProvider = auth.NewCachedTokenProvider(creds.TokenProvider, nil)
98			trans = &authTransport{
99				base:                         trans,
100				creds:                        creds,
101				clientUniverseDomain:         opts.UniverseDomain,
102				skipUniverseDomainValidation: skipUD,
103			}
104		}
105		return trans, nil
106	}
