626	func (h *otelHandler) handleRPCSuccess(span trace.Span) {
627		if span != nil {
628			attrs := []attribute.KeyValue{
629				attribute.String("rpc.response.status_code", "OK"),
630			}
631			span.SetAttributes(attrs...)
632		}
633	}
